<?php $e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); ?>
<h1 class="h3">Appearance</h1><p class="text-muted mb-4">Set the colors and default appearance of your public website.</p>
<form method="post" action="<?= url('admin/theme') ?>" style="max-width:760px"><section class="editor-panel"><h2 class="h5 mb-4">Website colors</h2><?php foreach(['primary_color'=>['Brand color','#7b3fe4','Buttons, links and highlights.'],'secondary_color'=>['Muted text','#6c757d','Supporting text throughout your pages.'],'accent_color'=>['Success accent','#198754','Success messages and confirmation states.']] as $key=>[$label,$default,$hint]): ?><div class="d-flex align-items-center gap-3 mb-4"><input type="color" class="form-control form-control-color" id="<?= $key ?>" name="<?= $key ?>" value="<?= $e($theme_data[$key]??$default) ?>"><div><label class="form-label mb-0" for="<?= $key ?>"><?= $label ?></label><div class="field-hint"><?= $hint ?></div></div></div><?php endforeach; ?></section><section class="editor-panel"><h2 class="h5">Light & dark mode</h2><label class="form-label mt-3" for="theme_default">Default appearance</label><select class="form-select mb-3" id="theme_default" name="theme_default"><?php foreach(['light','dark'] as $mode): ?><option value="<?= $mode ?>" <?= ($theme_data['theme_default']??'light')===$mode?'selected':'' ?>><?= ucfirst($mode) ?></option><?php endforeach; ?></select><label><input type="checkbox" name="dark_mode_enabled" value="1" <?= ($theme_data['dark_mode_enabled']??'1')!=='0'?'checked':'' ?>> Let visitors switch between light and dark</label></section><details class="editor-panel"><summary>Advanced: custom CSS</summary><label class="form-label" for="custom_css">Additional website styles</label><textarea class="form-control font-monospace" id="custom_css" name="custom_css" rows="8" maxlength="50000"><?= $e($theme_data['custom_css']??'') ?></textarea></details><button class="btn btn-primary" type="submit">Save appearance</button></form>